ee:message.ee:set-payload:
%dw 2.0 output application/csv separator=",", header=true
// RG1 : TEXTE_01 -> typeOccupation var mapRG1 = { "ACCT" : "M", "CLD" : "M", "LM" : "M", "CLM" : "M", "MO" : "M", "MP" : "M" }
// RG2 : TEXTE_01 -> natureOccupation var mapRG2 = { "ACCT": "Accident de travail", "CLD": "Congé longue durée", "LM": "Congé longue maladie", "MO": "Congé maladie ordinaire", "MP": "Maladie professionnelle" }
// RG3/RG4 : dd/MM/yyyy -> yyyyMMddHHmmss fun transformDate(date: String): String = (date as Date {format: "dd/MM/yyyy"} as String {format: "yyyyMMdd"}) ++ "000000"
// RG5 : LIG fun transformOperation(LIG) = if (LIG == "SUP") "S" else if (LIG == "CRE") "X" else ""
--- payload map(item) ->{ "matricule": item.CODSEL, "codeCentre": "", "typeOccupation": mapRG1[item.TEXTE_01] default "", "natureOccupation": mapRG2[item.TEXTE_01] default "", "dateDebut" : transformDate(item.DATDEB) ++ item.VALORIS_01, "dateFin" : transformDate(item.DATFIN) ++ item.VALORIS_01, "statut": "", "poids": "", "tempsTravail": "", "tempsPresenceHeures": "", "tempsPresenceMinutes": "", "idTypeCompteur": "", "nbTitreRestaurant": "", "commentaire": "", "operation": transformOperation(item.LIG) }
